topics.syntax:
for x in iterable:
    if condicion:
        continue

examples.code:
for n in [1, 2, 3, 4]:
    if n % 2 == 0:
        continue
    print(n)
# 1
# 3

for n in [1, 2, 3]:
    if n == 5:
        break
else:
    print("no encontrado")
# no encontrado
